on conflict (id) do update set
  importe_bruto = excluded.importe_bruto,
  importe_neto  = excluded.importe_neto,
  unidades      = excluded.unidades;

commit;

-- comprobacion
select periodo, count(*) as filas, count(distinct obra_id) as obras,
       round(sum(importe_bruto)::numeric,2) as bruto,
       round(sum(importe_neto)::numeric,2) as neto
  from public.obra_ingresos group by periodo order by periodo;
